import{b as e,O as p,g as t,j as l}from"./chunks/framework.DcaUmd3X.js";const i=JSON.parse('{"title":"三体全集（全三册）","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/three-body/index.md","filePath":"读书感悟/电子书架/19.三体全集.md","lastUpdated":1781614933000}'),c={name:"reading/digital/three-body/index.md"};function u(a,o,b,q,k,r){return p(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="三体全集-全三册" tabindex="-1">三体全集（全三册） <a class="header-anchor" href="#三体全集-全三册" aria-label="Permalink to &quot;三体全集（全三册）&quot;">​</a></h1><p><code>刘慈欣</code> <code>科幻小说</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 一个高尚的人，一个纯粹的人，一个有道德的人，一个脱离了低级趣味的人。”</p></blockquote><blockquote><p>📌 爱你，与你有何相干</p></blockquote><blockquote><p>📌 通过忠实地映射宇宙来隐藏自我，是融入永恒的唯一途径。</p></blockquote><blockquote><p>📌 罗辑与三体世界对视了五十四年，他由一个玩世不恭的人，变成一位面壁五十四年的真正面壁者，一位五十四年执剑待发的地球文明的守护人。</p></blockquote><blockquote><p>📌 我说过，我们是一个完整的世界，这个世界中的所有人都是普通人，但命运把我们推到了对两个世界做出最后审判的位置上。</p></blockquote><blockquote><p>📌 方寸之间，深不见底啊。</p></blockquote><blockquote><p>📌 弱小和无知不是生存的障碍，傲慢才是。</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 降维打击</p><p>📌 你们是虫子！</p></blockquote><blockquote><p>💭 无情啊</p><p>📌 我说，你们还是不要浪费纳税人的钱吧。</p></blockquote><blockquote><p>💭 这战争真有意思。</p><p>📌 有的，只是与你们相比十分简陋。比如在我们世界的战争中，敌对双方也会对自己的阵地进行伪装，但如果敌人对伪装的区域产生了怀疑，直接向对方询问，那他们一般都会得到真相的。</p></blockquote><blockquote><p>💭 这比洗脑还恐怖阿，反正最后都活不了，但是还是要为你死心塌地的做事情。</p><p>📌 好的，我去完成，照伊文斯的要求去完成。主，我们会证明自己的忠诚。</p></blockquote><blockquote><p>💭 抓到常人抓不到的重点，这是一种能力</p><p>📌 这冷静来自于我的玩世不恭，这世界上很难有什么东西让我在意。</p></blockquote><blockquote><p>💭 这就是爱的不够满的原因。</p><p>📌 不是的，大部分人的爱情对象也只是存在于自己的想象之中。他们所爱的并不是现实中的她（他），而只是想象中的她（他），现实中的她（他）只是他们创造梦中情人的一个模板，他们迟早会发现梦中情人与模板之间的差异，如果适应这种差异他们就会走到一起，无法适应就分开，就这么简单。你与大多数人的区别在于：你不需要模板。</p></blockquote><blockquote><p>💭 罗辑懵了</p><p>📌 我们怎么知道您是不是在工作？</p></blockquote><blockquote><p>💭 伏笔来了</p><p>📌 他的破壁人也只能是我了</p></blockquote><blockquote><p>💭 黑暗森林法则</p><p>📌 我们知道他对主的威胁是什么吗？</p></blockquote><blockquote><p>💭 讨论？讨论给智子听吗</p><p>📌 行星防御理事会第一次面壁者听证会已经进行了三天，泰勒、雷迪亚兹和希恩斯三位面壁者分别在会议上陈述了自己的第一阶段计划，PDC常任理事国代表对这些计划进行了初步的讨论</p></blockquote><blockquote><p>💭 给岁月以文明，而不是给文明以岁月。</p><p>📌 给岁月以文明，而不是给文明以岁月。</p></blockquote><blockquote><p>💭 过度的自信了</p><p>📌 “为什么不呢？我们在创造历史！”</p></blockquote><blockquote><p>💭 重点来了</p><p>📌 地球上是可以的，但在宇宙中不行。下面我们引入一个重要概念：猜疑链。”</p></blockquote><blockquote><p>💭 人性啊</p><p>📌 不时有城里来的人聚集在罗辑所住的楼下，对他起哄嘲骂，还向他的窗子扔石块，而新闻媒体对这景象也很感兴趣，往往来的记者和抗议者一样多。但罗辑被驱逐的真正原因，还是冬眠者们心中对他彻底的失望。</p></blockquote><blockquote><p>💭 代码也是一样</p><p>📌 在三维世界里，人类的视觉面对的是有限细节，一个环境或事物不管多么复杂，呈现的细节是有限的，只要用足够的时间依次观看，总能把绝大部分细节尽收眼底。</p></blockquote><blockquote><p>💭 降维打击？</p><p>📌 经观测发现，这些长线都出现在四维碎块的边缘，仿佛有一支无形的巨笔，不断地在太空中标示出四维与三维的交界线。</p></blockquote><blockquote><p>💭 最终还是要为自己的无知付出代价</p><p>📌 这是一个十分复杂的过程，由世界民意形成的政治压力促成了当时联合国和舰队国际的最后决定，人们激烈地争论着该由谁负责，但几乎没有人提出这是所有人的群体意志导致的结果。</p></blockquote><blockquote><p>💭 这个人的人设是在映射什么吗</p><p>📌 AA低声说：“这老家伙很精，留下了最贵的一幅。”</p></blockquote><blockquote><p>💭 看看你都干了什么？！</p><p>📌 孩子，看看你干了什么？</p></blockquote><blockquote><p>💭 这…</p><p>📌 程心也坐下来，伏在他的肩上笑着说：“可你是宇宙中唯一的男人了，不需要再送什么。”</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>一边感叹作者的脑洞的同时对宇宙星空的敬畏越来越深</p></blockquote>',33)])])}const n=e(c,[["render",u]]);export{i as __pageData,n as default};
